  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the rationale and a primary source on every
  -- row — scripts/test-mapping-discipline.mjs requires both. Each rationale names the
  -- division, title or section it is read from and states what the instrument DOES, not
  -- what anyone said about it. ON CONFLICT (measure_id, issue_key) DO NOTHING, so a
  -- re-emission of a live row is a no-op and cannot rewrite a rationale another
  -- migration authored.

  -- H.R. 7148 (119th) — strong_defense yea_supports w70 PRIMARY, israel_support yea_supports w50, health_rural yea_supports w45, foreign_balance yea_supports w40, health_drug_prices yea_supports w40, pro_life yea_supports w35
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_7148, 'strong_defense', 70, true, 'yea_supports',
      'Division A is the entire FY2026 Department of Defense appropriation, Titles I-VIII, and is the largest division of the act by dollars. Sec. 8143 adds $1,000,000,000 in Defense-Wide operation and maintenance for the Taiwan Security Cooperation Initiative. A yea enacts those levels; a nay blocks the package that carries them.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm'),
    (m_119_h_r_7148, 'israel_support', 50, false, 'yea_supports',
      'Division A Sec. 8071 appropriates $500,000,000 for Israeli Cooperative Programs: $60,000,000 Iron Dome, $127,000,000 Short-Range Ballistic Missile Defense, $40,000,000 SRBMD co-production, $100,000,000 upper-tier Israeli Missile Defense Architecture and Arrow 3 co-production, and $173,000,000 Arrow System Improvement Program. Division F Sec. 7041(c) directs not less than $3,300,000,000 in Foreign Military Financing grants only for Israel, disbursed within 30 days of enactment, plus not less than $250,300,000 for procurement in Israel. Division G Sec. 101 bars any contribution, grant or other payment to UNRWA.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm'),
    (m_119_h_r_7148, 'health_rural', 45, false, 'yea_supports',
      'Division J extends the rural and safety-net health authorities that were otherwise expiring: Sec. 6105(b) eliminates the scheduled Medicaid disproportionate share hospital allotment reductions, Sec. 6201 continues the increased inpatient adjustment for low-volume hospitals, Sec. 6202 extends the Medicare-Dependent Hospital program, Sec. 6203 extends the ground ambulance add-on payments, Sec. 6209 extends the Medicare telehealth flexibilities, and Sec. 6401 funds community health centers, the National Health Service Corps and teaching health center graduate medical education.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm'),
    (m_119_h_r_7148, 'foreign_balance', 40, false, 'yea_supports',
      'Division F Titles I, IV and V fund the diplomatic and allied-military instruments and the multilateral institutions: diplomatic programs $9,358,236,000, Foreign Military Financing $6,158,397,000, International Military Education and Training $119,152,000, peacekeeping operations $335,458,000, International Development Association $1,066,184,000, International Organizations and Programs $339,000,000, Global Environment Facility $150,200,000, and contributions to the Asian Development Fund and the African Development Bank. Scoped to allied military cooperation and multilateral institutions, per the rule recorded in 20260726120000_vr_coverage_pass_mappings.sql; general aid levels are not read as this axis.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm'),
    (m_119_h_r_7148, 'health_drug_prices', 40, false, 'yea_supports',
      'Division J regulates pharmacy benefit managers directly. Sec. 6702 requires a PBM to pass 100 percent of rebates through to the plan and makes a non-conforming arrangement a prohibited transaction under ERISA section 408(b)(2), with a 30-month effective date and an innocent-fiduciary exception; Sec. 6701 imposes oversight and reporting on PBM services; Sec. 6703 requires generic drug application transparency; and Secs. 6223-6224 add pharmacy access and choice protections and further PBM accountability requirements.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm'),
    (m_119_h_r_7148, 'pro_life', 35, false, 'yea_supports',
      'The act carries abortion-funding restrictions across four divisions: Division B Secs. 506-507 bar Labor-HHS funds for abortion with the standing life, rape and incest exceptions; Division E Sec. 613 bars abortion coverage in federal employee health plans; Division E Sec. 810 applies the same bar to District of Columbia funds; and Division F Sec. 7018 bars part I Foreign Assistance Act funds for abortion as a method of family planning. Recorded neutrally and weighted low, following the treatment of the same rider class on H.R. 6703 in 20260721160000_seed_legislation_deepdive3.sql: these are continuations of long-standing riders, not a new position taken on this vote.',
      'https://www.govinfo.gov/content/pkg/PLAW-119publ75/html/PLAW-119publ75.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 8595 (119th) — gov_services yea_supports w100 PRIMARY, strong_defense yea_supports w60, israel_support yea_supports w55, pro_life yea_supports w35
  --   Both new axes are read off the engrossed text at
  --   https://www.govinfo.gov/content/pkg/BILLS-119hr8595eh/html/BILLS-119hr8595eh.htm,
  --   not off the title. The live gov_services and strong_defense rows below are
  --   byte-identical re-emissions under runbook rule 20 so the seed mirror is complete; ON
  --   CONFLICT makes them no-ops, and rule 21 leaves their rationales with their first
  --   writer.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_8595, 'gov_services', 100, true, 'yea_supports',
      'Full-year appropriations bill funding the Department of State and related international programs; a yea keeps those federal operations and programs funded for FY2027.',
      'https://www.congress.gov/bill/119th-congress/house-bill/8595'),
    (m_119_h_r_8595, 'strong_defense', 60, false, 'yea_supports',
      'The same Act makes the FY2027 appropriations for national security programs; a yea funds them.',
      'https://www.congress.gov/bill/119th-congress/house-bill/8595'),
    (m_119_h_r_8595, 'israel_support', 55, false, 'yea_supports',
      'Sec. 7048(d) bars funds for the United Nations Human Rights Council, the Commission of Inquiry on the Occupied Palestinian Territory, East Jerusalem and Israel, and the Office of the High Commissioner for Human Rights. Sec. 7048(e) makes the bar on UNRWA permanent across this and prior Acts and extends it to soliciting UNRWA funds from other donors. Sec. 7049 conditions United Nations Secretariat funding on written assurance that UNRWA staff immunities will not be asserted for terrorism, material support or gross human-rights violations, and on inspector-general oversight of Gaza activities and the October 7, 2023 attacks. Sec. 7004(e) bars moving the United States embassy to Israel out of Jerusalem, and Sec. 7041(c) directs not less than $3,300,000,000 in Foreign Military Financing grants only for Israel.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr8595eh/html/BILLS-119hr8595eh.htm'),
    (m_119_h_r_8595, 'pro_life', 35, false, 'yea_supports',
      'Sec. 7018 bars funds made available to carry out part I of the Foreign Assistance Act of 1961 from paying for abortion as a method of family planning or from motivating or coercing any person to practice abortion. Recorded neutrally and weighted low on the H.R. 6703 precedent: a continuation of a long-standing rider rather than a new position taken on this vote.',
      'https://www.govinfo.gov/content/pkg/BILLS-119hr8595eh/html/BILLS-119hr8595eh.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's measure and roll so it can
-- only ever fail on data this migration is responsible for. A global count would drag
-- in every appropriations mapping earlier passes wrote and stop meaning anything.
--
-- The mapping count asserts >= because H.R. 8595 carries two live rows this pass
-- re-emits as no-ops, and because nothing here forbids a later pass from adding an
-- axis. The member-vote count asserts = on the one roll this migration creates: it is
-- created here and nowhere else, so the exact number is knowable and a short write is
-- a real failure rather than a race.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  m_id integer;
  rc_id integer;
  n integer;
BEGIN
  SELECT id INTO m_id FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119 AND chamber = 'house' AND number = 'H.R. 7148' LIMIT 1;
  IF m_id IS NULL THEN
    RAISE EXCEPTION 'Verification: H.R. 7148 (119th house) is missing after the pass.';
  END IF;

  SELECT count(*) INTO n FROM vr_measure_issues WHERE measure_id = m_id;
  IF n < 6 THEN
    RAISE EXCEPTION 'Verification: H.R. 7148 carries % issue mappings, expected at least 6.', n;
  END IF;

  SELECT id INTO rc_id FROM vr_rollcalls
   WHERE chamber = 'house' AND congress = 119 AND session = 2 AND roll_number = 53 LIMIT 1;
  IF rc_id IS NULL THEN
    RAISE EXCEPTION 'Verification: house 119/2 roll 53 is missing after the pass.';
  END IF;
  IF (SELECT measure_id FROM vr_rollcalls WHERE id = rc_id) IS DISTINCT FROM m_id THEN
    RAISE EXCEPTION 'Verification: roll 53 is attached to the wrong measure.';
  END IF;

  SELECT count(*) INTO n FROM vr_member_votes WHERE rollcall_id = rc_id;
  IF n <> 108 THEN
    RAISE EXCEPTION 'Verification: roll 53 carries % member votes, expected 108.', n;
  END IF;

  -- Shape check, scoped to the one roll this pass created. There is no politicians
  -- TABLE to join against — vr_member_votes.politician_id is a text slug with no
  -- foreign key, resolved in application code through db/vr-member-map.json, and
  -- scripts/test-vr-vote-seed.mjs is what proves every slug resolves. What SQL can
  -- prove here is that no row went in blank or with a position the reader cannot
  -- interpret.
  SELECT count(*) INTO n FROM vr_member_votes mv
   WHERE mv.rollcall_id = rc_id
     AND (mv.politician_id IS NULL
          OR btrim(mv.politician_id) = ''
          OR mv.position NOT IN ('yea', 'nay', 'present', 'not_voting'));
  IF n > 0 THEN
    RAISE EXCEPTION 'Verification: % member votes on roll 53 have a blank member or an unreadable position.', n;
  END IF;

  -- The two axes this pass adds to the already-live H.R. 8595 must land on the 119th
  -- Congress bill and not on a same-numbered measure from another Congress.
  SELECT id INTO m_id FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119 AND chamber = 'house' AND number = 'H.R. 8595' LIMIT 1;
  IF m_id IS NULL THEN
    RAISE EXCEPTION 'Verification: H.R. 8595 (119th house) is missing after the pass.';
  END IF;
  SELECT count(*) INTO n FROM vr_measure_issues
   WHERE measure_id = m_id AND issue_key IN ('israel_support', 'pro_life');
  IF n <> 2 THEN
    RAISE EXCEPTION 'Verification: H.R. 8595 carries % of the 2 new axes.', n;
  END IF;
END $$;
